export const BUFR_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/bufr-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getBufrStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(BUFR_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
